{:db/id 17592186184155 :knowledge-point/canonical-example {:db/id 17592186184059 :question/id #uuid "8f99b603-2fba-5a58-9966-b91d3a8a773e" :question/math-academy-id "e-373" :question/problem "Calculate $\displaystyle \int \left( 5(\sqrt{x})^{3} - 4 x^2 + 5\right) \,\textrm d x.$" :question/worked-solution "Using the sum and constant factor rules, we get

$$
\begin{aligned}\int (5(\sqrt{x})^{3}-4{x}^{2}+5)\,\text{d}x & =\int (5{x}^{3/2}-4{x}^{2}+5)\,\text{d}x \\  & =5\int {x}^{3/2}\,\text{d}x-4\int {x}^{2}\text{d}x+5\int 1\,\text{d}x \\  & =5\left(\frac{{x}^{5/2}}{\frac{5}{2}}\right)-4\left(\frac{{x}^{3}}{3}\right)+5(x)+C \\  & =5\cdot \frac{2}{5}{x}^{5/2}-\frac{4}{3}{x}^{3}+5x+C \\  & =2\sqrt{{x}^{5}}-\frac{4}{3}{x}^{3}+5x+C.\end{aligned}
$$"} :knowledge-point/id #uuid "007f3355-427a-5da4-8af7-22581f1cb1de" :knowledge-point/questions [{:db/id 17592186184563 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "9e5ce597-62ea-54d2-8f1a-415f3eedcc86" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{x^{3} - 3\sqrt{x^{3}} + 6x}{3} + C" :db/id 17592186181503} {:answer/id #uuid "c47182fe-b5f7-5ab7-9468-8e985b6c0a96" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{x^{3} - 2\sqrt{x^{3}} + 2x}{3} + C" :db/id 17592186181504} {:answer/id #uuid "c8c0f99f-f43c-5656-ad88-f62d9b27ccb1" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{x^{3} + 2\sqrt[3]{x^{2}} + 2x}{3} + C" :db/id 17592186181505} {:answer/id #uuid "39ee7c07-44d7-5ef5-97de-7c0090d83f08" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{x^{3} + 3\sqrt{x^{3}} + 6x}{3} + C" :db/id 17592186181506} {:answer/id #uuid "5e14c783-f2a2-5eff-9bda-e48e2bc22284" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{x^{3} - 2\sqrt{x^{3}} + 6x}{3} + C" :db/id 17592186181507}] :answer-field/id #uuid "55fc02a1-3a57-558e-b923-8f00b33126b5" :answer-field/key "selection" :answer-field/type {:db/ident :answer-field.type/radio} :db/id 17592186181502}] :question/id #uuid "564c4689-85ae-5d46-8778-645d30c6800f" :question/math-academy-id "q-2250" :question/problem "What is $\displaystyle \int(x^{2} - \sqrt{x} + 2)dx$?"} {:db/id 17592186184739 :question/answer-fields [{:answer-field/choices [{:answer/id #uuid "b0295760-ce95-592b-8918-47e98fff062e" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{x^{8}}{4} + \frac{5\sqrt[6]{x^{5}}}{6} + \frac{7}{6\sqrt[7]{x^{6}}} + C" :db/id 17592186183049} {:answer/id #uuid "c1baca12-4645-57ec-bb80-522c579d2dc2" :answer/type {:db/ident :answer.type/math} :answer/value "\frac{x^{8}}{2} + \frac{5\sqrt[5]{x^{6}}}{6} + \frac{7}{6\sqrt[7]{x^{6}}} + C" :db/id 17592186183050} {:answer/id #uuid "f62c1c24-e30c-5d3a-89bc-93a36f6194ce" :answer/type {:db/ident